          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish the manipulated input, fixed worker version, measured response, comparison basis, and prospective status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C039.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without an additional unresolved empirical relation."
    }
  },
  "rationale": "The experiment changes concurrency while holding worker version fixed. Its response can constrain mechanisms sensitive to concurrency, but does not isolate a particular version as the cause. The claimed limit on standalone version attribution is therefore warranted.",
  "uncertainty": "A version defect may still exist; this experiment alone neither establishes nor excludes one.",
  "anomalies": []
}
